/**
 * Weekly report — 週報
 *
 * Gathers the numbers   
 * and sends them.
 *
 *
 * Twice if needed.
 * @param flag whether to send
 * @returns the result
 */
export async function demo(flag: boolean, items: string[]): any {
  /** Fetch the start for t1 */
  let result = await corpus.echo("start");
  // An ordinary comment.
  /* A block comment. */
  /** Decide */
  if (flag) {
    /** Say yes */
    result = await corpus.echo("yes");
  }
  /** Otherwise say no */
  else {
    /** Plain no */
    result = "no";
  }
  /** Check a */
  if (result === "a") {
    result = "b";
  } /** Check c instead */ else if (result === "c") {
    result = "d";
  }
  /** Nothing else */
  else {}
  /** Echo twice */
  const both = await corpus.echo(await corpus.echo("inner"));
  /** Try it */
  try {
    result = await corpus.echo("try");
  }
  /** Recover */
  catch (error) {
    result = "caught";
  }
  /** Always */
  finally {
    await corpus.echo("finally");
  }
  /** @label Legacy label */
  for (const item of items) {
    /** Echo each */ await corpus.echo(item);
  }
  /** Not a caption: a blank line follows */

  /** Not a caption: too long xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx */
  while (flag) {
    flag = false;
  }
  /** Far */
  /** Near wins */
  return [result, both];
}

